import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with Loon?","description":"How to move Loon subscriptions, nodes, configuration, plugin, rewrite and script needs to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with Loon?","description":"How to move Loon subscriptions, nodes, configuration, plugin, rewrite and script needs to Clash for iOS.","head":[["meta",{"name":"keywords","content":"Loon to Clash,Loon subscription,Loon nodes,Loon configuration,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I use a Loon subscription in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the provider returns mihomo YAML from an HTTPS subscription URL. Parameters from Loon node text, standalone links or Base64 lists can also be organized as YAML or entered manually.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can Loon nodes be used in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Shared protocols including Shadowsocks, ShadowsocksR, VMess, VLESS, Trojan, HTTP, SOCKS, WireGuard, Hysteria2 and AnyTLS can be reused with matching parameters.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move Loon plugins, rewrites and scripts?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Recreate the original plugin, rewrite and script needs with mihomo configuration, Clash rules and matching features.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/loon.md","filePath":"guide/compatibility/loon.md","lastUpdated":0}`),a={name:`guide/compatibility/loon.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-loon" tabindex="-1">Is Clash compatible with Loon? <a class="header-anchor" href="#is-clash-compatible-with-loon" aria-label="Permalink to “Is Clash compatible with Loon?”">​</a></h1><p><strong>Shared node protocols continue to work, while the original routing experience can be recreated in Clash.</strong></p><p>Loon has its own syntax for nodes, rules, policies, rewrites, scripts and plugins. When moving to Clash, continue using provider subscriptions and nodes through compatible formats, then recreate rules and extension features with matching Clash capabilities.</p><h2 id="which-loon-nodes-can-be-reused" tabindex="-1">Which Loon nodes can be reused? <a class="header-anchor" href="#which-loon-nodes-can-be-reused" aria-label="Permalink to “Which Loon nodes can be reused?”">​</a></h2><p>According to the <a href="https://nsloon.app/docs/Node/" target="_blank" rel="noreferrer">official Loon node documentation</a>, protocols shared by both apps include:</p><ul><li>Shadowsocks and ShadowsocksR;</li><li>VMess and VLESS;</li><li>Trojan;</li><li>HTTP / HTTPS and SOCKS5;</li><li>WireGuard;</li><li>Hysteria2;</li><li>AnyTLS.</li></ul><p>Match the transport, TLS, Reality, obfuscation, encryption, authentication and UDP options to get the complete protocol experience.</p><h2 id="how-do-i-migrate-a-loon-subscription" tabindex="-1">How do I migrate a Loon subscription? <a class="header-anchor" href="#how-do-i-migrate-a-loon-subscription" aria-label="Permalink to “How do I migrate a Loon subscription?”">​</a></h2><ol><li>Try adding the same subscription URL to Clash.</li><li>If the provider selects output by client, change the subscription User-Agent and choose Clash / mihomo output.</li><li>When the provider offers Loon-specific text, select its mihomo YAML output.</li><li>Organize standalone link parameters as mihomo YAML, or add them in the node editor.</li></ol><h2 id="what-to-recreate-in-clash" tabindex="-1">What to recreate in Clash <a class="header-anchor" href="#what-to-recreate-in-clash" aria-label="Permalink to “What to recreate in Clash”">​</a></h2><ul><li>organize nodes, rules and policy groups as mihomo YAML;</li><li>recreate plugin, rewrite and JavaScript needs with matching Clash features;</li><li>express Custom by JS connection needs with protocols available in Clash;</li><li>set app preferences, certificates and local data to match your workflow.</li></ul><p>Loon defines a plugin as a collection of rules, rewrites and scripts. In Clash, map those needs to rules and matching features for a clear, maintainable setup.</p><h2 id="can-i-keep-using-the-same-server" tabindex="-1">Can I keep using the same server? <a class="header-anchor" href="#can-i-keep-using-the-same-server" aria-label="Permalink to “Can I keep using the same server?”">​</a></h2><p>The same node can work when both apps support its protocol and every required parameter has an equivalent.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>, or see <a href="/clash.md/guide/protocols">all supported protocols</a>.</p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};